// Le rapport automatique n'est envoyé qu'UNE fois par jour : au premier
// passage où le PC est allumé après 7h. Les passages suivants s'arrêtent ici.
// Un lancement manuel passe toujours.
const memoire = $getWorkflowStaticData('global');
const aujourdhui = $now.setZone('Europe/Paris').toISODate();
// Lancement automatique = le bloc de planification a été déclenché.
// (Attention : $execution.mode vaut « production » et non « trigger » dans un bloc Code.)
const automatique = $('Toutes les heures (7h-21h)').isExecuted;
if (automatique && memoire.dernierEnvoi === aujourdhui) return [];
// silencieux = appelé par le podcast : on renvoie les données au lieu d'envoyer le message
const entree = $input.first().json;
// ignorer : le bot n'a pas besoin de la journée pour cette question -> on s'arrête tout de suite
if (entree.ignorer === true) return [];
const silencieux = entree.silencieux === true;
// detail : le bot veut les titres et sujets (jamais demandé par le podcast)
const detail = entree.detail === true;
return [{ json: { aujourdhui, silencieux, detail } }];

// Un élément par agenda visible (hors "Numéros de semaine").
// L'agenda principal est toujours inclus, même en cas d'erreur de la liste.
const r = $input.first().json;
const cals = (r.items ?? []).filter(k => k.primary || (k.selected !== false && !k.id.includes('#weeknum')));
if (r.error || !cals.length) return [{ json: { id: 'primary', nom: '' } }];
return cals.map(k => ({ json: { id: k.id, nom: k.primary ? '' : (k.summaryOverride ?? k.summary) } }));

// Transforme la liste de mails en un élément par mail.
// S'il n'y a aucun mail, on émet quand même un élément vide pour que la
// chaîne continue vers le compte suivant.
const r = $input.first().json;
if (r.error || !r.messages?.length) return [{ json: { id: null } }];
return r.messages.map(m => ({ json: { id: m.id } }));

// Un élément par agenda visible (hors "Numéros de semaine").
// L'agenda principal est toujours inclus, même en cas d'erreur de la liste.
const r = $input.first().json;
const cals = (r.items ?? []).filter(k => k.primary || (k.selected !== false && !k.id.includes('#weeknum')));
if (r.error || !cals.length) return [{ json: { id: 'primary', nom: '' } }];
return cals.map(k => ({ json: { id: k.id, nom: k.primary ? '' : (k.summaryOverride ?? k.summary) } }));

// Transforme la liste de mails en un élément par mail.
// S'il n'y a aucun mail, on émet quand même un élément vide pour que la
// chaîne continue vers le compte suivant.
const r = $input.first().json;
if (r.error || !r.messages?.length) return [{ json: { id: null } }];
return r.messages.map(m => ({ json: { id: m.id } }));

// Un élément par agenda visible (hors "Numéros de semaine").
// L'agenda principal est toujours inclus, même en cas d'erreur de la liste.
const r = $input.first().json;
const cals = (r.items ?? []).filter(k => k.primary || (k.selected !== false && !k.id.includes('#weeknum')));
if (r.error || !cals.length) return [{ json: { id: 'primary', nom: '' } }];
return cals.map(k => ({ json: { id: k.id, nom: k.primary ? '' : (k.summaryOverride ?? k.summary) } }));

// Transforme la liste de mails en un élément par mail.
// S'il n'y a aucun mail, on émet quand même un élément vide pour que la
// chaîne continue vers le compte suivant.
const r = $input.first().json;
if (r.error || !r.messages?.length) return [{ json: { id: null } }];
return r.messages.map(m => ({ json: { id: m.id } }));

// Assemble le rapport à partir des blocs précédents.
// Par sécurité, on n'envoie que l'expéditeur et le sujet (jamais le contenu),
// et les suites de chiffres sont masquées (codes de vérification, 2FA...).
const COMPTES = ['Compte1', 'Compte2', 'Compte3'];
const ECOLE = /school\.example/i;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const court = (s, n = 90) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const masquer = s => s.replace(/\d[\d -]{2,}\d/g, m => (m.replace(/\D/g, '').length >= 4 ? '••••' : m));
const lire = nom => { try { return $(nom).all().map(i => i.json); } catch { return []; } };
const expediteur = from => (from.match(/^\s*"?([^"<]+?)"?\s*</)?.[1] ?? from).trim();

const erreurs = [];
const evenements = [];
const dejaVus = new Set();
const ecole = [];
const importants = {};

for (const c of COMPTES) {
  // Les réponses "Agenda – X" sont dans le même ordre que les agendas listés
  const cals = lire(`Un élément par agenda – ${c}`);
  const reponses = lire(`Agenda – ${c}`);
  if (!reponses.length || reponses.every(r => r.error)) erreurs.push(`Agenda ${c}`);
  reponses.forEach((r, i) => {
    if (r.error) return;
    const cal = cals[i] ?? {};
    const ferie = String(cal.id).includes('#holiday');
    for (const e of r.items ?? []) {
      if (e.status === 'cancelled') continue;
      const debut = e.start?.dateTime ?? e.start?.date;
      const jour = DateTime.fromISO(debut, { zone: 'Europe/Paris' }).setZone('Europe/Paris').toISODate();
      // Un même jour férié ou anniversaire peut exister dans plusieurs comptes : on ne le garde qu'une fois
      const cle = ferie ? 'ferie' + jour : (e.summary ?? '') + debut;
      if (dejaVus.has(cle)) continue;
      dejaVus.add(cle);
      evenements.push({
        compte: c,
        agenda: cal.nom,
        titre: e.summary ?? '(sans titre)',
        debut,
        jour,
        journee: !e.start?.dateTime,
        lieu: e.location,
        type: ferie ? 'ferie' : e.eventType,
      });
    }
  });

  const liste = lire(`Mails – ${c}`)[0];
  if (!liste || liste.error) { erreurs.push(`Gmail ${c}`); continue; }
  const plus = liste.nextPageToken ? 1 : 0;

  for (const m of lire(`Détails – ${c}`)) {
    if (!m.payload) continue; // élément vide ou erreur
    const h = n => m.payload.headers?.find(x => x.name.toLowerCase() === n)?.value ?? '';
    const mail = { compte: c, de: expediteur(h('from')), sujet: masquer(h('subject') || '(sans sujet)') };
    if (ECOLE.test(h('from') + h('to') + h('cc'))) ecole.push(mail);
    else (importants[c] ??= []).push(mail);
  }
  if (plus) (importants[c] ??= []).push({ de: '…', sujet: "et d'autres (plus de 25)" });
}

evenements.sort((a, b) => (a.journee === b.journee ? String(a.debut).localeCompare(String(b.debut)) : a.journee ? -1 : 1));

const L = [];
const jour = $now.setZone('Europe/Paris').setLocale('fr').toFormat('cccc d LLLL');
L.push(`☀️ <b>Rapport du ${jour}</b>`);

const ICONES = { birthday: '🎂', ferie: '🇫🇷' };
function agenda(titre, liste) {
  L.push('', `<b>${titre} (${liste.length})</b>`);
  if (!liste.length) L.push('Rien de prévu.');
  for (const e of liste) {
    const h = e.journee ? '' : `<b>${DateTime.fromISO(e.debut).setZone('Europe/Paris').toFormat("HH'h'mm")}</b> `;
    const ou = e.type === 'ferie' ? '' : ` <i>(${e.compte}${e.agenda ? ' · ' + esc(e.agenda) : ''})</i>`;
    L.push(`• ${ICONES[e.type] ?? '📌'} ${h}${esc(court(e.titre))}${e.lieu ? ` — <i>${esc(court(e.lieu, 40))}</i>` : ''}${ou}`);
  }
}
const ajd = $now.setZone('Europe/Paris').toISODate();
const demain = $now.setZone('Europe/Paris').plus({ days: 1 }).toISODate();
const evAjd = evenements.filter(e => e.jour <= ajd); // <= : inclut les événements sur plusieurs jours déjà commencés
const evDemain = evenements.filter(e => e.jour === demain);
agenda("📅 Aujourd'hui", evAjd);
agenda('🔜 Demain', evDemain);

// Résumé général pour le podcast : volontairement SANS titres ni noms
const resume = l => ({
  rendez_vous: l.filter(e => !['birthday', 'ferie'].includes(e.type))
    .map(e => (e.journee ? 'toute la journée' : DateTime.fromISO(e.debut).setZone('Europe/Paris').toFormat("HH'h'mm"))),
  anniversaires: l.filter(e => e.type === 'birthday').length,
  jours_feries: l.filter(e => e.type === 'ferie').map(e => e.titre), // noms publics (ex : Toussaint)
});

L.push('', `<b>🎓 École — non lus (${ecole.length})</b>`);
if (!ecole.length) L.push('Rien de nouveau.');
for (const m of ecole) L.push(`• <b>${esc(court(m.de, 40))}</b> — ${esc(court(m.sujet))}`);

const nb = Object.values(importants).flat().length;
L.push('', `<b>📬 Mails importants non lus (${nb})</b>`);
if (!nb) L.push('Rien d\'important. 👌');
for (const c of COMPTES) {
  if (!importants[c]) continue;
  L.push(`<u>${c}</u>`);
  for (const m of importants[c]) L.push(`• <b>${esc(court(m.de, 40))}</b> — ${esc(court(m.sujet))}`);
}

if (erreurs.length) L.push('', `⚠️ Indisponible : ${erreurs.join(', ')}`);

const messages = [];
let courant = '';
for (const l of L) {
  if (courant.length + l.length + 1 > 4000) { messages.push(courant); courant = ''; }
  courant += (courant ? '\n' : '') + l;
}
if (courant) messages.push(courant);
const nbImportants = Object.values(importants).flat().filter(m => m.de !== '…').length;
const donnees = {
  aujourdhui: resume(evAjd),
  demain: resume(evDemain),
  mails_ecole_non_lus: ecole.length,
  mails_importants_non_lus: nbImportants,
  sources_indisponibles: erreurs,
};
// Version détaillée, réservée au bot (titres d'événements, expéditeurs et sujets de mails)
const detail = {
  evenements: [...evAjd, ...evDemain].map(e => ({
    jour: e.jour === demain ? 'demain' : "aujourd'hui",
    heure: e.journee ? 'toute la journée' : DateTime.fromISO(e.debut).setZone('Europe/Paris').toFormat("HH'h'mm"),
    titre: e.titre, compte: e.compte, type: e.type === 'birthday' ? 'anniversaire' : e.type === 'ferie' ? 'jour férié' : 'événement',
  })),
  mails_ecole_non_lus: ecole.map(m => ({ de: m.de, sujet: m.sujet })),
  mails_importants_non_lus: importants,
};
return messages.map(texte => ({ json: { texte, donnees, detail } }));

// Mémorise que le rapport automatique du jour est parti (seulement APRÈS l'envoi réussi)
if (!$('Toutes les heures (7h-21h)').isExecuted) return [];
$getWorkflowStaticData('global').dernierEnvoi = $('Déjà envoyé aujourd\'hui ?').first().json.aujourdhui;
return [];

// Renvoyé à l'appelant : résumé général (podcast), plus le détail seulement si le bot l'a demandé
const { donnees, detail } = $input.first().json;
return [{ json: $('Déjà envoyé aujourd\'hui ?').first().json.detail ? { ...donnees, detail } : donnees }];
